    "picker.vault": "Prefix Vault", "picker.vaultSub": "Guard six slots and push prefix hit rate toward 90%.", "vault.kicker": "MINICC ARCADE · PREFIX ECONOMY", "vault.title": "Prefix Vault · Keep the hot context close", "vault.subtitle": "Every request carries a prefix signature. Hit a cached prefix to score; miss one and lose a life. Slots are finite — decide who stays.", "vault.back": "Back to arcade", "vault.how": "Guide", "vault.close": "Close Prefix Vault", "vault.score": "Score", "vault.hitRate": "Hit rate", "vault.wave": "Wave", "vault.combo": "Combo", "vault.lives": "Lives", "vault.best": "Best", "vault.ready": "Ready", "vault.running": "Guarding", "vault.gameOver": "Out of lives", "vault.start": "Start game", "vault.again": "Play again", "vault.incoming": "Incoming request", "vault.token": "tokens", "vault.cache": "Put in an empty slot", "vault.cacheHint": "Reserve an empty slot for a prefix that will return; costs a few tokens", "vault.evict": "Evict least recently used", "vault.evictHint": "When full, drop the oldest prefix and store the current request", "vault.slot": "Cache slot", "vault.used": "last hit", "vault.empty": "empty", "vault.hint": "Click the slot with the same prefix to score · filling a slot costs tokens · when full, evict the least recently used", "vault.howTitle": "Five steps to Prefix Vault", "vault.howSub": "Every rule mirrors a real cache strategy. Play once and it sticks.", "vault.how1t": "Read the prefix", "vault.how1": "The letter on the request card is its prefix signature. Click the slot with the same letter to hit it — in the real project, byte-stable prefixes are what make a cache hit.", "vault.how2t": "Do not guess", "vault.how2": "A wrong slot or a timed-out request is a miss: you lose one life and the combo resets. Five misses end the run.", "vault.how3t": "Empty slots are not free", "vault.how3": "Putting a request into an empty slot costs tokens and scores nothing. Only reserve a slot when you expect that prefix again.", "vault.how4t": "Eviction is the skill", "vault.how4": "When every slot is full, evict the least recently used prefix and store the current one. Hit rate comes from choosing well, not from having more slots.", "vault.how5t": "Watch session affinity", "vault.how5": "One letter suddenly goes hot for a while, like a real conversation reusing the same context. Ride the hot prefix, then evict it when the surge passes.", "vault.howReady": "I am ready",
